<?php $success = sessionSuccess(); $error = sessionError(); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Notifications - DormSync</title><style>*{box-sizing:border-box}body{background:#f7f9fc;color:#172033;font-family:Arial,sans-serif;margin:0}main{max-width:1000px;margin:auto;padding:40px 24px}.topbar{background:#fff;border-bottom:1px solid #e7ebf2;padding:18px 6%}.topbar a{color:#2563eb}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:24px;margin-top:20px}.notice{border-bottom:1px solid #e7ebf2;padding:14px 0}.notice:last-child{border-bottom:0}.actions{float:right}.action{background:#eef4ff;border:1px solid #bfdbfe;border-radius:5px;color:#1d4ed8;padding:6px 8px}.danger{background:#fef2f2;border-color:#fecaca;color:#b91c1c}.message{padding:10px;background:#dcfce7;color:#166534}</style></head><body><header class="topbar"><a href="/admin/dashboard">Back to dashboard</a></header><main><h1>System Notifications</h1><?php if($success):?><div class="message"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($error):?><div class="message"><?=htmlspecialchars($error)?></div><?php endif;?><p><a class="action" href="/admin/notice-create">Create notice</a></p><section class="panel"><?php if($notices): foreach($notices as $notice):?><article class="notice"><div class="actions"><form method="post" action="/admin/notice-delete/<?= (int)$notice['id'] ?>"><button class="action danger" type="submit">Delete</button></form></div><strong><?=htmlspecialchars($notice['title'])?></strong><p><?=htmlspecialchars($notice['message'])?></p><small><?=htmlspecialchars($notice['scope'])?> · <?=htmlspecialchars($notice['author'])?></small></article><?php endforeach; else:?><p>No notices available.</p><?php endif;?></section></main></body></html>